"""生成双语 Notebook / Generate the bilingual notebook."""
from pathlib import Path
import nbformat as nbf
OUT = Path(__file__).resolve().parents[1]
cells = [
    nbf.v4.new_markdown_cell('# 航班延误探索性分析 / Exploratory analysis of flight delays\n\n本 Notebook 读取清洗后的航班与衔接表，通过六组图展示延误分布、日期和时段差异、航司与机场差异，以及前后航班的延误变化。\n\n阅读方式：先看图前的说明，再看图和图后结果。延误率指延误至少 15 分钟的航班比例。\n\nThis notebook reads the cleaned flight and connection tables. Six sets of charts describe delay distributions, date and time-of-day patterns, airline and airport differences, and delay changes between consecutive flights.\n\nRead each explanation before the chart, followed by the reported results. A delay rate is the proportion of flights delayed by at least 15 minutes.'),
    nbf.v4.new_code_cell('from pathlib import Path\nimport json\nimport numpy as np\nimport pandas as pd\nimport matplotlib.pyplot as plt\nimport matplotlib.dates as mdates\nfrom matplotlib import font_manager\nimport seaborn as sns\nfrom IPython.display import display\n\ndef find_output_dir():\n    here = Path.cwd().resolve()\n    candidates = [here, *here.parents]\n    for p in candidates:\n        if p.name == "output_A" and p.is_dir():\n            return p\n        if (p / "output_A").is_dir():\n            return p / "output_A"\n        if (p / "airline_delay" / "output_A").is_dir():\n            return p / "airline_delay" / "output_A"\n    raise FileNotFoundError("未找到 output_A / Start from output_A or the project directory.")\n\nOUTPUT = find_output_dir()\nDATA = OUTPUT / "data"\nTABLES = OUTPUT / "tables"\nFIGURES = OUTPUT / "figures"\nTABLES.mkdir(parents=True, exist_ok=True)\nFIGURES.mkdir(parents=True, exist_ok=True)\nfont_candidates = ["Arial Unicode MS", "Microsoft YaHei", "SimHei", "Noto Sans CJK SC", "PingFang SC", "Heiti TC"]\navailable_fonts = {item.name for item in font_manager.fontManager.ttflist}\nchinese_font = next((name for name in font_candidates if name in available_fonts), "DejaVu Sans")\nif chinese_font == "DejaVu Sans":\n    print("中文字体未找到 / Install a Chinese font and restart the kernel to display Chinese labels.")\nsns.set_theme(style="whitegrid", font=chinese_font)\nplt.rcParams["axes.unicode_minus"] = False\n\nflights_path = DATA / "flights_clean.csv.gz"\nconnections_path = DATA / "flight_connections.csv.gz"\nif not flights_path.exists() or not connections_path.exists():\n    missing = [str(p) for p in (flights_path, connections_path) if not p.exists()]\n    raise FileNotFoundError("缺少输入数据 / Missing input data: " + "；".join(missing))\n\nflight_required = ["FlightDate", "Reporting_Airline", "Origin", "Dest", "Cancelled", "Diverted", "DepDelayMinutes", "ArrDelayMinutes", "DepDel15", "ArrDel15", "DayOfWeek", "Distance", "flight_id", "scheduled_dep_hour", "normal_operation", "time_valid"]\nconnection_required = ["connection_id", "airport", "upstream_airline", "downstream_airline", "upstream_arr_delay_minutes", "downstream_dep_delay_minutes", "scheduled_turnaround_minutes", "actual_ground_minutes", "delta_delay_minutes", "overnight_scheduled", "downstream_flight_date"]\nflights = pd.read_csv(flights_path, usecols=flight_required, parse_dates=["FlightDate"], dtype={"flight_id": "string"})\nconnections = pd.read_csv(connections_path, usecols=connection_required, parse_dates=["downstream_flight_date"], dtype={"connection_id": "string"})\nassert set(flight_required) <= set(flights.columns), f"航班字段缺失 / Missing flight columns: {sorted(set(flight_required)-set(flights.columns))}"\nassert set(connection_required) <= set(connections.columns), f"衔接字段缺失 / Missing connection columns: {sorted(set(connection_required)-set(connections.columns))}"\ndef as_bool(series):\n    if pd.api.types.is_bool_dtype(series):\n        return series.astype("boolean")\n    if pd.api.types.is_numeric_dtype(series):\n        values = series.dropna()\n        assert values.isin([0, 1]).all(), f"布尔字段取值 / Boolean values must be 0 or 1: {sorted(values.unique())}"\n        return series.astype("boolean")\n    text = series.astype("string").str.strip().str.lower()\n    mapped = text.map({"true": True, "false": False, "1": True, "0": False, "1.0": True, "0.0": False})\n    assert mapped.notna().sum() == series.notna().sum(), f"布尔字段无法解析 / Unrecognised boolean values: {sorted(text[series.notna() & mapped.isna()].unique())}"\n    return mapped.astype("boolean")\n\nassert as_bool(pd.Series([0.0, 1.0, np.nan])).iloc[:2].tolist() == [False, True]\nassert as_bool(pd.Series([True, False])).tolist() == [True, False]\nassert as_bool(pd.Series(["0", "1", "0.0", "1.0", "false", "true"])).tolist() == [False, True, False, True, False, True]\n\nfor col in ["Cancelled", "Diverted", "normal_operation", "time_valid"]:\n    flights[col] = as_bool(flights[col])\nconnections["overnight_scheduled"] = as_bool(connections["overnight_scheduled"])\nsample_period = f"{flights[\'FlightDate\'].min():%Y-%m} to {flights[\'FlightDate\'].max():%Y-%m}"\nprint(f"航班 / Flights: {len(flights):,}; 航司 / Airlines: {flights[\'Reporting_Airline\'].nunique():,}; 出发机场 / Origin airports: {flights[\'Origin\'].nunique():,}; 有效衔接 / Connections: {len(connections):,}")\nmonthly = (flights.assign(month=flights["FlightDate"].dt.to_period("M").astype(str))\n           .groupby("month", as_index=False)\n           .agg(flight_n=("flight_id", "size"), cancelled_n=("Cancelled", "sum"), cancelled_label_n=("Cancelled", "count"),\n                diverted_n=("Diverted", "sum"), diverted_label_n=("Diverted", "count")))\nmonthly["cancelled_rate_pct"] = monthly["cancelled_n"] / monthly["cancelled_label_n"].replace(0, np.nan) * 100\nmonthly["diverted_rate_pct"] = monthly["diverted_n"] / monthly["diverted_label_n"].replace(0, np.nan) * 100\nmonthly.to_csv(TABLES / "eda_monthly_overview.csv", index=False)\nprint(f"样本期 / Period: {sample_period}; 月度概况 / Monthly overview:")\ndisplay(monthly)\n'),
    nbf.v4.new_markdown_cell('## 1. 延误分布 / Delay distributions\n\n横轴是延误分钟，纵轴是航班数；左图为出发，右图为到达。提前和准点统一记为零。图展示 0—180 分钟，右侧长尾所占比例标在图内。\n\nThe x-axis shows delay minutes and the y-axis shows flight counts: departure on the left and arrival on the right. Early and on-time flights are recorded as zero. The charts show 0–180 minutes and annotate the share beyond 180 minutes.'),
    nbf.v4.new_code_cell('def nonnegative_delay(series):\n    x = pd.to_numeric(series, errors="coerce")\n    return x[x.notna() & (x >= 0)]\n\ndep = nonnegative_delay(flights["DepDelayMinutes"])\narr = nonnegative_delay(flights["ArrDelayMinutes"])\nfig, axes = plt.subplots(1, 2, figsize=(15, 5), sharey=True)\nfor ax, values, title in [(axes[0], dep, "出发延误 / Departure delay"), (axes[1], arr, "到达延误 / Arrival delay")]:\n    ax.hist(values[values <= 180], bins=np.arange(0, 181, 10), color="#4472C4", edgecolor="white")\n    ax.set(title=f"{title}\\n0–180 min | {sample_period}", xlabel="延误分钟 / Delay (min)", ylabel="航班数 / Flights")\n    ax.text(.98, .96, f"有效记录 / Available n={len(values):,}\\n>180 min={((values > 180).mean()*100 if len(values) else np.nan):.2f}%", transform=ax.transAxes, ha="right", va="top", fontsize=9, bbox={"facecolor":"white", "alpha":.85, "edgecolor":"none"})\nfig.tight_layout()\nfig.savefig(FIGURES / "eda_01_delay_distributions.png", dpi=160, bbox_inches="tight")\nplt.show()\nfor label, values in [("出发 / Departure", dep), ("到达 / Arrival", arr)]:\n    tail = (values > 180).mean() if len(values) else np.nan\n    print(f"{label}: 图示 / Shown {int((values <= 180).sum()):,}/{len(values):,}; 超过 / Above 180 min: {tail:.2%}")'),
    nbf.v4.new_markdown_cell('## 2. 每日延误率 / Daily delay rates\n\n每个点表示当天有出发延误标签的航班中，晚出发至少 15 分钟的比例。例如 25% 表示每四班约有一班延误。\n\nEach point is the share of flights departing at least 15 minutes late among flights with an available departure-delay label that day. A value of 25% means approximately one delayed flight in four.'),
    nbf.v4.new_code_cell('daily = (flights.dropna(subset=["FlightDate", "DepDel15"])\n         .groupby("FlightDate", as_index=False)\n         .agg(sample_n=("DepDel15", "size"), delay_rate=("DepDel15", "mean")))\ndaily["delay_rate_pct"] = daily["delay_rate"] * 100\nassert int(daily["sample_n"].sum()) == int(flights["DepDel15"].notna().sum())\ndaily.to_csv(TABLES / "eda_daily_departure_delay_rate.csv", index=False)\nfig, ax = plt.subplots(figsize=(12, 4.5))\nax.plot(daily["FlightDate"], daily["delay_rate_pct"], color="#4472C4", linewidth=1.4)\nax.set(title=f"每日出发延误率 / Daily departure delay rate\\n{sample_period}", xlabel="航班日期 / Flight date", ylabel="延误率 / Delay rate (%)")\ntick_dates = list(pd.date_range(daily["FlightDate"].min(), daily["FlightDate"].max(), freq="10D"))\nif tick_dates[-1] != daily["FlightDate"].max():\n    tick_dates.append(daily["FlightDate"].max())\nax.set_xticks(tick_dates)\nax.xaxis.set_major_formatter(mdates.DateFormatter("%m-%d"))\nax.set_xlim(daily["FlightDate"].min(), daily["FlightDate"].max())\nfig.tight_layout(); fig.savefig(FIGURES / "eda_02_daily_departure_rate.png", dpi=160, bbox_inches="tight"); plt.show()\nprint(f"日期数 / Days: {len(daily):,}; 日延误率中位数 / Median daily rate: {daily[\'delay_rate_pct\'].median():.2f}%; 范围 / Range: {daily[\'delay_rate_pct\'].min():.2f}%–{daily[\'delay_rate_pct\'].max():.2f}%")'),
    nbf.v4.new_markdown_cell('## 3. 计划出发小时与星期 / Scheduled departure hour and weekday\n\n横轴是星期，纵轴是出发机场当地计划出发小时；例如 20 表示 20:00—20:59。左图颜色和数字表示延误率，右图表示对应航班数。两张图一起阅读，可以同时了解延误水平与样本规模。\n\nThe x-axis is weekday; the y-axis is the scheduled departure hour in the origin airport’s local time. For example, 20 covers 20:00–20:59. The left panel shows delay rates; the right panel shows the corresponding flight counts. Read both panels together to see the rate and sample size.'),
    nbf.v4.new_code_cell('hour_day = (flights.dropna(subset=["scheduled_dep_hour", "DayOfWeek", "DepDel15"])\n            .groupby(["scheduled_dep_hour", "DayOfWeek"], as_index=False)\n            .agg(sample_n=("DepDel15", "size"), delay_rate=("DepDel15", "mean")))\nhour_day["delay_rate_pct"] = hour_day["delay_rate"] * 100\nhour_weekday_valid = flights[["scheduled_dep_hour", "DayOfWeek", "DepDel15"]].notna().all(axis=1).sum()\nassert int(hour_day["sample_n"].sum()) == int(hour_weekday_valid)\nhour_day.to_csv(TABLES / "eda_hour_weekday_groups.csv", index=False)\nrate_p = hour_day.pivot(index="scheduled_dep_hour", columns="DayOfWeek", values="delay_rate_pct")\nn_p = hour_day.pivot(index="scheduled_dep_hour", columns="DayOfWeek", values="sample_n")\nday_values = sorted(hour_day["DayOfWeek"].dropna().unique())\nweekday_names = ["周一\\nMon", "周二\\nTue", "周三\\nWed", "周四\\nThu", "周五\\nFri", "周六\\nSat", "周日\\nSun"]\nassert set(day_values) <= set(range(1, 8)) or set(day_values) <= set(range(7)), f"星期编码异常 / Invalid weekday code: {day_values}"\nday_names = {v: weekday_names[int(v) - 1] for v in day_values} if set(day_values) <= set(range(1, 8)) else {v: weekday_names[int(v)] for v in day_values}\nrate_p = rate_p.rename(columns=day_names); n_p = n_p.rename(columns=day_names)\nday_order = [day_names[v] for v in day_values]\nrate_p = rate_p.reindex(columns=day_order); n_p = n_p.reindex(columns=day_order)\nn_annot = n_p.apply(lambda col: col.map(lambda x: "" if pd.isna(x) else f"{int(x):,}"))\nfig, axes = plt.subplots(1, 2, figsize=(14, 11))\nsns.heatmap(rate_p, cmap="YlOrRd", annot=True, fmt=".1f", annot_kws={"size": 7}, cbar_kws={"label":"延误率 / Delay rate (%)"}, ax=axes[0])\naxes[0].set(title=f"出发延误率 / Departure delay rate\\n{sample_period}", xlabel="星期 / Weekday", ylabel="当地计划出发小时 / Scheduled local hour")\naxes[0].set_xticklabels(axes[0].get_xticklabels(), rotation=0)\naxes[0].set_yticklabels([str(int(v)) for v in rate_p.index], rotation=0)\nsns.heatmap(n_p, cmap="Blues", annot=n_annot, fmt="", annot_kws={"size": 6}, cbar_kws={"label":"航班数 / Flights (n)"}, ax=axes[1])\naxes[1].set(title="对应航班数 / Corresponding flight counts", xlabel="星期 / Weekday", ylabel="当地计划出发小时 / Scheduled local hour")\naxes[1].set_xticklabels(axes[1].get_xticklabels(), rotation=0)\naxes[1].set_yticklabels([str(int(v)) for v in n_p.index], rotation=0)\nfig.tight_layout(); fig.savefig(FIGURES / "eda_03_hour_weekday.png", dpi=160, bbox_inches="tight"); plt.show()\nlowest = hour_day.loc[hour_day["sample_n"].idxmin()]\nhighest = hour_day.loc[hour_day["delay_rate"].idxmax()]\nprint(f"时段组 / Hour-weekday groups: {len(hour_day):,}; 最小组 / Smallest group: n={int(lowest[\'sample_n\'])}; 最高延误率 / Highest rate: {highest[\'delay_rate_pct\']:.2f}% (n={int(highest[\'sample_n\'])})")'),
    nbf.v4.new_markdown_cell('## 4. 航司与出发机场 / Airlines and origin airports\n\n样本为未取消、未备降的航班。左侧条形表示航班量，右侧圆点表示延误率。上下两行分别比较航司与航班量前 15 的出发机场。机场的衔接延误变化由 B 在有效衔接表中进一步分析。\n\nThe sample consists of non-cancelled, non-diverted flights. Bars on the left show flight counts; dots on the right show delay rates. The rows compare airlines and the 15 busiest origin airports. B will analyse connection-level delay changes separately using the eligible connection table.'),
    nbf.v4.new_code_cell('normal = flights.loc[flights["normal_operation"].fillna(False).astype(bool)].copy()\ndef group_normal(col):\n    out = (normal.dropna(subset=[col]).groupby(col, as_index=False)\n           .agg(flight_n=("flight_id", "size"), label_n=("DepDel15", "count"),\n                delayed_n=("DepDel15", "sum"), delay_rate=("DepDel15", "mean")))\n    out["delay_rate_pct"] = out["delay_rate"] * 100\n    return out\nairline = group_normal("Reporting_Airline").sort_values("flight_n", ascending=False)\nairport = group_normal("Origin").sort_values("flight_n", ascending=False)\nairport_top = airport.head(15).copy()\nassert int(airline["flight_n"].sum()) == len(normal.dropna(subset=["Reporting_Airline"]))\nassert int(airport["flight_n"].sum()) == len(normal.dropna(subset=["Origin"]))\nairline.to_csv(TABLES / "eda_airline_normal_operation.csv", index=False)\nairport.to_csv(TABLES / "eda_origin_airport_normal_operation.csv", index=False)\nfig, axes = plt.subplots(2, 2, figsize=(16, max(9, .4*max(len(airline), 15))), sharey="row")\nfor row, table, label, title in [(0, airline, "Reporting_Airline", "航司 / Airlines"), (1, airport_top, "Origin", "主要出发机场 / Top 15 origin airports")]:\n    d = table.sort_values("flight_n").reset_index(drop=True)\n    y = np.arange(len(d))\n    axes[row, 0].barh(y, d["flight_n"], color="#A9C4E4")\n    axes[row, 0].set(yticks=y, yticklabels=d[label].astype(str), xlabel="完成航班数 / Completed flights", title=f"{title}\\n航班数 / Flight count")\n    axes[row, 0].set_xlim(left=0)\n    axes[row, 1].scatter(d["delay_rate_pct"], y, color="#C0504D", s=28)\n    axes[row, 1].set(xlabel="延误率 / Delay rate (%)", title=f"{title}\\n出发延误率 / Departure delay rate")\n    axes[row, 1].set_xlim(left=0)\n    axes[row, 0].grid(axis="y", visible=False); axes[row, 1].grid(axis="y", visible=False)\nfig.suptitle(f"未取消且未备降航班 / Non-cancelled, non-diverted flights\\n{sample_period}", y=1.01)\nfig.tight_layout(); fig.savefig(FIGURES / "eda_04_airline_airport.png", dpi=160, bbox_inches="tight"); plt.show()\nprint(f"完成航班 / Completed flights: {len(normal):,}; 航司 / Airlines: {len(airline)}; 机场 / Airports: {len(airport)}; 展示航班量前 15 机场 / Showing the 15 busiest origin airports.")'),
    nbf.v4.new_markdown_cell('## 5. 前后航班延误 / Upstream and downstream delays\n\n横轴是上一班到达延误，纵轴是下一班出发延误。每个六边形汇总一小块区域内的衔接数量，越黄表示越多，色条使用对数刻度。红线表示前后延误相等；线上方为延误增加，下方为延误恢复。\n\n例如，上游晚到 60 分钟、下游晚出发 20 分钟，对应点在红线下方，表示恢复 40 分钟。\n\nThe x-axis is upstream arrival delay and the y-axis is downstream departure delay. Each hexagon counts connections in a small region: yellow indicates more records, using a logarithmic colour scale. The red line marks equal delays. Above it, delay increases; below it, delay is recovered.\n\nFor example, an upstream delay of 60 minutes and downstream delay of 20 minutes lies below the line and represents 40 minutes of recovery.'),
    nbf.v4.new_code_cell('xy = connections[["upstream_arr_delay_minutes", "downstream_dep_delay_minutes"]].apply(pd.to_numeric, errors="coerce").dropna()\nin_range = xy[(xy.iloc[:, 0] >= 0) & (xy.iloc[:, 0] <= 180) & (xy.iloc[:, 1] >= 0) & (xy.iloc[:, 1] <= 180)]\ncoverage = len(in_range) / len(xy) if len(xy) else np.nan\nfig, ax = plt.subplots(figsize=(10, 8))\nif len(in_range):\n    hb = ax.hexbin(in_range.iloc[:, 0], in_range.iloc[:, 1], gridsize=35, extent=(0,180,0,180), mincnt=1, bins="log", cmap="viridis")\n    fig.colorbar(hb, ax=ax, label="衔接数（对数刻度）\\nConnections (log scale)")\nax.plot([0,180], [0,180], color="#C0504D", linestyle="--", linewidth=1.5, label="延误相等 / Equal delays (y=x)")\nax.set(xlim=(0,180), ylim=(0,180), xlabel="上游到达延误 / Upstream arrival delay (min)", ylabel="下游出发延误 / Downstream departure delay (min)", title=f"前后航班延误 / Upstream and downstream delays\\n0–180 min | {sample_period}")\nax.legend(loc="upper left")\nax.text(.98,.03,f"图示 / Shown: {len(in_range):,}/{len(xy):,}\\n占比 / Share: {coverage:.2%}", transform=ax.transAxes, ha="right", va="bottom", bbox={"facecolor":"white","alpha":.85,"edgecolor":"none"})\nfig.tight_layout(); fig.savefig(FIGURES / "eda_05_connection_hexbin.png", dpi=160, bbox_inches="tight"); plt.show()\nprint(f"衔接 / Connections: {len(xy):,}; 图示 / Shown: {len(in_range):,} ({coverage:.2%})")'),
    nbf.v4.new_markdown_cell('## 6. 周转时间与延误变化 / Turnaround time and delay change\n\n选择上游到达延误至少 15 分钟、非隔夜的有效衔接。横轴是计划周转时间分组；纵轴是下游非负出发延误减去上游非负到达延误。负值表示恢复，正值表示增加。\n\n蓝点是中位数；竖线覆盖第 25—75 百分位，即中间 50% 的记录；n 是衔接数。计划周转时间是两班计划时刻之间的间隔。\n\nSelect eligible, non-overnight connections with upstream arrival delay of at least 15 minutes. The x-axis groups scheduled turnaround times. The y-axis is nonnegative downstream departure delay minus nonnegative upstream arrival delay: negative values indicate recovery and positive values indicate an increase.\n\nBlue dots are medians. Vertical bars span the 25th–75th percentiles, covering the middle 50% of records; n is the number of connections. Scheduled turnaround is the interval between the two scheduled timestamps.'),
    nbf.v4.new_code_cell('sub = connections.copy()\nfor c in ["upstream_arr_delay_minutes", "scheduled_turnaround_minutes", "delta_delay_minutes"]:\n    sub[c] = pd.to_numeric(sub[c], errors="coerce")\nsub = sub[(sub["upstream_arr_delay_minutes"] >= 15) &\n          (~sub["overnight_scheduled"].fillna(True).astype(bool)) &\n          (sub["scheduled_turnaround_minutes"] >= 0)]\nsub = sub.dropna(subset=["scheduled_turnaround_minutes", "delta_delay_minutes"])\nbins = [0, 30, 60, 90, 120, 180, np.inf]\nlabels = ["0–<30", "30–<60", "60–<90", "90–<120", "120–<180", "180+"]\nsub["turnaround_bin"] = pd.cut(sub["scheduled_turnaround_minutes"], bins=bins, labels=labels, right=False, include_lowest=True)\nturn = (sub.dropna(subset=["turnaround_bin"]).groupby("turnaround_bin", observed=False)\n        .agg(sample_n=("delta_delay_minutes", "size"), median=("delta_delay_minutes", "median"),\n             q25=("delta_delay_minutes", lambda x: x.quantile(.25)), q75=("delta_delay_minutes", lambda x: x.quantile(.75)))\n        .reset_index())\nassert int(turn["sample_n"].sum()) == len(sub.dropna(subset=["turnaround_bin"]))\nturn.to_csv(TABLES / "eda_turnaround_delta_summary.csv", index=False)\nfig, ax = plt.subplots(figsize=(13, 6))\nx = np.arange(len(turn)); med = turn["median"].to_numpy(); lo = med-turn["q25"].to_numpy(); hi = turn["q75"].to_numpy()-med\nax.errorbar(x, med, yerr=np.vstack([lo,hi]), fmt="o", capsize=5, color="#4472C4", ecolor="#8FAADC")\nfor xi, yi, n in zip(x, med, turn["sample_n"]): ax.annotate(f"n={n:,}",(xi,yi),xytext=(0,9),textcoords="offset points",ha="center",fontsize=8)\nax.axhline(0, color="gray", linewidth=1, linestyle="--")\nax.set(xticks=x, xticklabels=turn["turnaround_bin"].astype(str), xlabel="计划周转时间 / Scheduled turnaround (min)", ylabel="延误变化（下游 − 上游）\\nDelay change: downstream − upstream (min)", title=f"周转与延误变化 / Turnaround and delay change\\n上游延误 ≥15 分钟，非隔夜 / Upstream delay ≥15 min, non-overnight | {sample_period}")\nfig.tight_layout(); fig.savefig(FIGURES / "eda_06_turnaround_delta.png", dpi=160, bbox_inches="tight"); plt.show()\nnonempty = turn[turn["sample_n"] > 0]\nif len(nonempty):\n    lo_row = nonempty.loc[nonempty["median"].idxmin()]; hi_row = nonempty.loc[nonempty["median"].idxmax()]\n    print(f"入选衔接 / Selected connections: {len(sub):,}; 周转组 / Turnaround groups: {len(nonempty)}; 最低中位数 / Lowest median: {lo_row[\'turnaround_bin\']} ({lo_row[\'median\']:.1f} min); 最高 / Highest: {hi_row[\'turnaround_bin\']} ({hi_row[\'median\']:.1f} min)")\nelse:\n    print("该分组无记录 / No records in the selected turnaround groups.")'),
    nbf.v4.new_markdown_cell('## 汇总与下一步 / Summary and next steps\n\n完整分组统计保存在 `tables/`，六张图保存在 `figures/`。B 继续做机场比较；C、D 使用相同样本和时间划分比较线性回归与随机森林，并检验加入上游信息后的预测改善。\n\nFull grouped statistics are saved in `tables/`, and the six figures in `figures/`. B continues with airport comparisons. C and D use shared samples and chronological splits to compare linear regression and random forests, testing the improvement from adding upstream information.'),
    nbf.v4.new_code_cell('summary = {\n    "flights_rows": int(len(flights)),\n    "connections_rows": int(len(connections)),\n    "sample_period": sample_period,\n    "monthly_overview_csv": "eda_monthly_overview.csv",\n    "flight_date_min": None if flights["FlightDate"].dropna().empty else str(flights["FlightDate"].min().date()),\n    "flight_date_max": None if flights["FlightDate"].dropna().empty else str(flights["FlightDate"].max().date()),\n    "airlines": int(flights["Reporting_Airline"].nunique(dropna=True)),\n    "origin_airports": int(flights["Origin"].nunique(dropna=True)),\n    "dep_delay_nonnegative_nonnull_n": int(len(dep)),\n    "dep_delay_gt_180_share": None if dep.empty else float((dep > 180).mean()),\n    "arr_delay_nonnegative_nonnull_n": int(len(arr)),\n    "arr_delay_gt_180_share": None if arr.empty else float((arr > 180).mean()),\n    "daily_dates_with_label": int(len(daily)),\n    "daily_departure_delay_rate_median": None if daily.empty else float(daily["delay_rate"].median()),\n    "connection_nonnull_delay_pairs_n": int(len(xy)),\n    "connection_pairs_in_0_180_n": int(len(in_range)),\n    "connection_pairs_in_0_180_share": None if len(xy) == 0 else float(coverage),\n    "eligible_delayed_nonovernight_connections_n": int(len(sub)),\n    "eligible_connection_turnaround_groups": int((turn["sample_n"] > 0).sum()),\n}\n(TABLES / "eda_summary.json").write_text(json.dumps(summary, ensure_ascii=False, indent=2), encoding="utf-8")\nprint("已保存 / Saved: ", TABLES / "eda_summary.json")\ndisplay(pd.DataFrame([\n    {"指标 / Metric": "航班记录 / Flights", "值 / Value": f"{len(flights):,}"},\n    {"指标 / Metric": "有效衔接 / Connections", "值 / Value": f"{len(connections):,}"},\n    {"指标 / Metric": "样本期 / Period", "值 / Value": sample_period},\n    {"指标 / Metric": "出发延误有效记录 / Available departure delays", "值 / Value": f"{len(dep):,}"},\n    {"指标 / Metric": "到达延误有效记录 / Available arrival delays", "值 / Value": f"{len(arr):,}"},\n    {"指标 / Metric": "图示衔接比例 / Displayed connection share", "值 / Value": f"{coverage:.2%}"},\n    {"指标 / Metric": "上游延误且非隔夜 / Delayed upstream, non-overnight", "值 / Value": f"{len(sub):,}"},\n]))'),
]
